// tracker.js — Click event capture and batch sender
(function () {
  const BASE = window.REC_BASE || "";
  const SESSION_KEY = "rec_session_id";

  const SESSION_ID = (() => {
    let id = localStorage.getItem(SESSION_KEY);
    if (!id) {
      id = "sess_" + Math.random().toString(36).slice(2) + Date.now().toString(36);
      localStorage.setItem(SESSION_KEY, id);
    }
    return id;
  })();

  const queue = [];
  let flushTimer = null;

  function track(itemId, query = "", position = 0) {
    queue.push({ session_id: SESSION_ID, item_id: itemId, query, position });
    scheduleFlush();
  }

  function scheduleFlush() {
    if (!flushTimer) {
      flushTimer = setTimeout(flush, 2000);
    }
  }

  async function flush() {
    flushTimer = null;
    if (queue.length === 0) return;
    const batch = queue.splice(0, 100);
    try {
      await fetch(BASE + "/api/track", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ events: batch }),
      });
    } catch (e) {
      // Best-effort — drop events rather than block the UI
      console.warn("Tracker flush failed:", e);
    }
  }

  // Flush remaining events when the user leaves the page
  window.addEventListener("beforeunload", () => {
    if (queue.length > 0) {
      const blob = new Blob([JSON.stringify({ events: queue.splice(0) })], {
        type: "application/json",
      });
      navigator.sendBeacon(BASE + "/api/track", blob);
    }
  });

  window.Tracker = { track };
})();
